def silu(x):
    x=np.asarray(x,dtype=np.float64)
    return x/(1+np.exp(np.clip(-x,-500,500)))
def tri_coefs(period,phase,breaks):
    # tri(t): 1 at t=0 mod period, -1 at t=period/2, values at integers z>=0 written as a0 + sum c_k relu(z-k)
    def tri(t):
        t=(t%period); return 1-4*t/period if t<=period/2 else -3+4*t/period
    a0=tri(-phase); c={}
    prev=0.0; 
    ks=list(breaks)
    for i,k in enumerate(ks):
        nxt=ks[i+1] if i+1<len(ks) else k+period/4
