    zn=gated(0,S*x0,S*y0,S)
    brk=list(range(0,14,2));beta=10.0
    a1,c1,tri=tri_coefs(8,0,[0,4,8,12]);a2,c2,_=tri_coefs(8,2,[0,2,6,10])
