    pos=np.argsort(co)
    r=32.0-J; s_=31.5-pos
    for c in range(8):
        w3[c,gate2[2]]+=beta*(bin(c).count("1")-1.5)/G
    for k in range(3):
        u=np.where((la>>k)&1,r,-r);v=np.where((lb>>k)&1,s_,-s_)
